SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE `accounts_user` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `password` varchar(128) NOT NULL, `last_login` datetime(6) NULL, `is_superuser` bool NOT NULL, `username` varchar(150) NOT NULL UNIQUE, `first_name` varchar(150) NOT NULL, `last_name` varchar(150) NOT NULL, `email` varchar(254) NOT NULL, `is_staff` bool NOT NULL, `is_active` bool NOT NULL, `date_joined` datetime(6) NOT NULL, `role` varchar(20) NOT NULL, `phone` varchar(32) NOT NULL, `avatar_initials` varchar(4) NOT NULL, `home_property_id` bigint NULL, `welcome_offer_used` bool NOT NULL);
CREATE TABLE `accounts_user_groups` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `user_id` bigint NOT NULL, `group_id` integer NOT NULL);
CREATE TABLE `accounts_user_user_permissions` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `user_id` bigint NOT NULL, `permission_id` integer NOT NULL);
CREATE TABLE `django_admin_log` (`id` integer AUTO_INCREMENT NOT NULL PRIMARY KEY, `action_time` datetime(6) NOT NULL, `object_id` longtext NULL, `object_repr` varchar(200) NOT NULL, `action_flag` smallint UNSIGNED NOT NULL CHECK (`action_flag` >= 0), `change_message` longtext NOT NULL, `content_type_id` integer NULL, `user_id` bigint NOT NULL);
CREATE TABLE `auth_permission` (`id` integer AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` varchar(255) NOT NULL, `content_type_id` integer NOT NULL, `codename` varchar(100) NOT NULL);
CREATE TABLE `auth_group` (`id` integer AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` varchar(150) NOT NULL UNIQUE);
CREATE TABLE `auth_group_permissions` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `group_id` integer NOT NULL, `permission_id` integer NOT NULL);
CREATE TABLE `bookings_booking` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `code` varchar(24) NOT NULL UNIQUE, `guest_name` varchar(160) NOT NULL, `guest_email` varchar(254) NOT NULL, `guest_phone` varchar(32) NOT NULL, `check_in` date NOT NULL, `check_out` date NOT NULL, `rooms_count` smallint UNSIGNED NOT NULL CHECK (`rooms_count` >= 0), `adults` smallint UNSIGNED NOT NULL CHECK (`adults` >= 0), `children` smallint UNSIGNED NOT NULL CHECK (`children` >= 0), `status` varchar(16) NOT NULL, `source` varchar(10) NOT NULL, `currency` varchar(8) NOT NULL, `nightly_total` numeric(12, 2) NOT NULL, `service_total` numeric(12, 2) NOT NULL, `tax_total` numeric(12, 2) NOT NULL, `grand_total` numeric(12, 2) NOT NULL, `rate_details` json NOT NULL, `cancellation_reason` longtext NOT NULL, `cancellation_fee` numeric(12, 2) NOT NULL, `special_requests` longtext NOT NULL, `created_at` datetime(6) NOT NULL, `updated_at` datetime(6) NOT NULL, `created_by_id` bigint NULL, `guest_id` bigint NULL, `room_type_id` bigint NOT NULL, `discount_total` numeric(12, 2) NOT NULL, CONSTRAINT `booking_valid_range` CHECK (`check_out` > (`check_in`)));
CREATE TABLE `bookings_raterule` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` varchar(120) NOT NULL, `rule_type` varchar(12) NOT NULL, `start_date` date NOT NULL, `end_date` date NOT NULL, `multiplier` numeric(5, 3) NOT NULL, `priority` smallint UNSIGNED NOT NULL CHECK (`priority` >= 0), `is_active` bool NOT NULL, `room_type_id` bigint NULL, `property_id` bigint NULL, CONSTRAINT `rate_rule_valid_range` CHECK (`end_date` >= (`start_date`)));
CREATE TABLE `bookings_roomassignment` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `assigned_at` datetime(6) NOT NULL, `released_at` datetime(6) NULL, `assigned_by_id` bigint NULL, `booking_id` bigint NOT NULL, `room_id` bigint NOT NULL);
CREATE TABLE `django_content_type` (`id` integer AUTO_INCREMENT NOT NULL PRIMARY KEY, `app_label` varchar(100) NOT NULL, `model` varchar(100) NOT NULL);
CREATE TABLE `finance_invoice` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `number` varchar(24) NOT NULL UNIQUE, `status` varchar(12) NOT NULL, `subtotal` numeric(12, 2) NOT NULL, `service` numeric(12, 2) NOT NULL, `tax` numeric(12, 2) NOT NULL, `total` numeric(12, 2) NOT NULL, `issued_at` datetime(6) NOT NULL, `booking_id` bigint NOT NULL UNIQUE);
CREATE TABLE `finance_payment` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `method` varchar(16) NOT NULL, `amount` numeric(12, 2) NOT NULL, `currency` varchar(8) NOT NULL, `status` varchar(12) NOT NULL, `reference` varchar(64) NOT NULL, `note` varchar(255) NOT NULL, `created_at` datetime(6) NOT NULL, `booking_id` bigint NOT NULL, `created_by_id` bigint NULL, `invoice_id` bigint NULL);
CREATE TABLE `hotel_amenity` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` varchar(80) NOT NULL UNIQUE, `icon` varchar(40) NOT NULL);
CREATE TABLE `hotel_roomtype` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` varchar(120) NOT NULL, `slug` varchar(50) NOT NULL UNIQUE, `description` longtext NOT NULL, `base_price` numeric(10, 2) NOT NULL, `max_guests` smallint UNSIGNED NOT NULL CHECK (`max_guests` >= 0), `total_rooms` smallint UNSIGNED NOT NULL CHECK (`total_rooms` >= 0), `size_sqm` smallint UNSIGNED NOT NULL CHECK (`size_sqm` >= 0), `floor_range` varchar(32) NOT NULL, `bed_type` varchar(16) NOT NULL, `image_url` varchar(200) NOT NULL, `is_active` bool NOT NULL, `cancellation_days` smallint UNSIGNED NOT NULL CHECK (`cancellation_days` >= 0), `created_at` datetime(6) NOT NULL, `property_id` bigint NOT NULL);
CREATE TABLE `hotel_roomtype_amenities` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `roomtype_id` bigint NOT NULL, `amenity_id` bigint NOT NULL);
CREATE TABLE `hotel_room` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `number` varchar(12) NOT NULL, `floor` smallint UNSIGNED NOT NULL CHECK (`floor` >= 0), `status` varchar(20) NOT NULL, `notes` longtext NOT NULL, `updated_at` datetime(6) NOT NULL, `room_type_id` bigint NOT NULL, `property_id` bigint NULL, CONSTRAINT `unique_room_number_per_property` UNIQUE (`property_id`, `number`));
CREATE TABLE `hotel_property` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` varchar(120) NOT NULL, `slug` varchar(50) NOT NULL UNIQUE, `tagline` varchar(160) NOT NULL, `description` longtext NOT NULL, `city` varchar(80) NOT NULL, `country` varchar(80) NOT NULL, `address` varchar(200) NOT NULL, `phone` varchar(32) NOT NULL, `email` varchar(254) NOT NULL, `stars` smallint UNSIGNED NOT NULL CHECK (`stars` >= 0), `currency` varchar(8) NOT NULL, `service_rate` numeric(4, 3) NOT NULL, `tax_rate` numeric(4, 3) NOT NULL, `check_in_hour` smallint UNSIGNED NOT NULL CHECK (`check_in_hour` >= 0), `check_out_hour` smallint UNSIGNED NOT NULL CHECK (`check_out_hour` >= 0), `image_url` varchar(200) NOT NULL, `is_active` bool NOT NULL, `created_at` datetime(6) NOT NULL, `vibe_tags` varchar(160) NOT NULL, `latitude` double precision NULL, `longitude` double precision NULL);
CREATE TABLE `hotel_attraction` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `name` varchar(120) NOT NULL, `blurb` varchar(200) NOT NULL, `icon` varchar(40) NOT NULL, `distance` varchar(24) NOT NULL, `sort` smallint UNSIGNED NOT NULL CHECK (`sort` >= 0), `property_id` bigint NOT NULL, `latitude` double precision NULL, `longitude` double precision NULL);
CREATE TABLE `operations_maintenancerequest` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `title` varchar(160) NOT NULL, `description` longtext NOT NULL, `severity` varchar(10) NOT NULL, `status` varchar(12) NOT NULL, `created_at` datetime(6) NOT NULL, `resolved_at` datetime(6) NULL, `reported_by_id` bigint NULL, `room_id` bigint NOT NULL);
CREATE TABLE `operations_housekeepingtask` (`id` bigint AUTO_INCREMENT NOT NULL PRIMARY KEY, `task_type` varchar(16) NOT NULL, `status` varchar(12) NOT NULL, `priority` varchar(8) NOT NULL, `notes` longtext NOT NULL, `created_at` datetime(6) NOT NULL, `started_at` datetime(6) NULL, `completed_at` datetime(6) NULL, `assigned_to_id` bigint NULL, `booking_id` bigint NULL, `room_id` bigint NOT NULL);
CREATE TABLE `django_session` (`session_key` varchar(40) NOT NULL PRIMARY KEY, `session_data` longtext NOT NULL, `expire_date` datetime(6) NOT NULL);
CREATE TABLE `django_migrations` (`id` bigint NOT NULL AUTO_INCREMENT, `app` varchar(255) NOT NULL, `name` varchar(255) NOT NULL, `applied` datetime(6) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `django_migrations_app_name` (`app`,`name`)) ENGINE=InnoDB;
